const glossary = {
  "Max drawdown": ["The largest peak-to-trough fall over a measured period.", "This portfolio shows a −14.2% illustrative drawdown versus −10.8% for the S&P 500. The extra downside comes from concentrated growth exposure."],
  "Sharpe ratio": ["Excess return earned per unit of historical volatility.", "A 1.18 sample Sharpe is stronger than the benchmark, but it is backward-looking and sensitive to the time window."],
  "Beta": ["Sensitivity to broad-market movement; 1.0 roughly matches the market.", "The 1.16 portfolio beta suggests a 1% market move could translate to about a 1.16% portfolio move, before company-specific effects."],
  "Tracking error": ["How differently a portfolio moves from its benchmark.", "The 8.4% estimate is meaningful because this is a focused portfolio, not an S&P 500 substitute."],
  "ROA": ["Return on assets measures how efficiently a company turns its asset base into profit.", "Compare ROA within similar business models. Asset-light software and semiconductor firms can naturally differ from retailers or banks."],
  "P/E ratio": ["Share price divided by earnings per share: the price paid for one dollar of earnings.", "A high P/E may reflect superior growth, but it also increases the cost of disappointment."],
  "Gross margin": ["Revenue left after direct costs, before operating expenses.", "Margin direction helps separate durable pricing power from growth that requires rising costs."],
  "Diversification": ["Combining return drivers so one company or theme does not dominate outcomes.", "Four allocations diversify by name, but the portfolio remains concentrated in US mega-cap growth."],
  "Model confidence": ["A stability score for evidence coverage, profile fit and agent agreement.", "It is not a probability of profit. Current confidence is reduced by valuation and NVIDIA event risk."],
} as const;
type GlossaryTerm = keyof typeof glossary;

